import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import {
  collectChangeModels,
  emitChangesDts,
  emitChangesJs,
  emitModelsDts,
  emitModelsJs,
} from "./changes.js";
import { emitClientDts, emitClientJs } from "./client.js";
import { loadDocument, makeTypes, type OpenApiDocument } from "./openapi.js";

export interface GenerateOptions {
  input: string | URL | OpenApiDocument;
  output?: string;
}

const GENERATED_HEADER =
  "/* Generated by @sparsetypes/codegen. Do not edit directly. */";
const DEFAULT_OUTPUT = "node_modules/@sparsetypes/generated";

export async function generate({
  input,
  output,
}: GenerateOptions): Promise<void> {
  if (!input || output === "")
    throw new TypeError("Input and a non-empty output path are required.");
  const document = await loadDocument(input);
  // Resolve reusable parameter references before type generation so local
  // #/components/parameters/... problems report actionable codegen errors
  // instead of generic schema-resolution failures.
  const clientDts = emitClientDts(document);
  const clientJs = emitClientJs(document);
  const apiTypes = await makeTypes(document);
  const changeModels = collectChangeModels(document);
  const files = {
    "api.d.ts": apiTypes,
    "models.d.ts": emitModelsDts(document, changeModels),
    "models.js": emitModelsJs(document, changeModels),
    "changes.js": emitChangesJs(changeModels),
    "changes.d.ts": emitChangesDts(changeModels),
    "client.js": clientJs,
    "client.d.ts": clientDts,
    "index.js": `export { createClient, ApiError } from "./client.js";\nexport * from "./changes.js";\nexport * from "./models.js";`,
    "index.d.ts": `export { createClient, ApiError } from "./client.js";\nexport type { ClientOptions, ApiClient } from "./client.js";\nexport * from "./changes.js";\nexport * from "./models.js";`,
    "package.json": JSON.stringify(
      {
        name: "@sparsetypes/generated",
        private: true,
        type: "module",
        types: "./index.d.ts",
        exports: { ".": { types: "./index.d.ts", import: "./index.js" } },
      },
      null,
      2,
    ),
  };
  const destination = path.resolve(output ?? DEFAULT_OUTPUT);
  await mkdir(destination, { recursive: true });
  for (const [file, contents] of Object.entries(files)) {
    const generated =
      file === "package.json"
        ? `${contents.trimEnd()}\n`
        : `${GENERATED_HEADER}\n${contents.trimEnd()}\n`;
    await writeFile(path.join(destination, file), generated, "utf8");
  }
}
